import{_ as r,I as i,c as o,o as n,ag as a,J as s}from"./chunks/framework.Vyheyqg9.js";const f=JSON.parse('{"title":"Git, CI and release integrity","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/delivery.md","filePath":"engineering/delivery.md"}'),c={name:"engineering/delivery.md"};function l(d,e,h,p,_,u){const t=i("MermaidDiagram");return n(),o("div",null,[e[0]||(e[0]=a('<h1 id="git-ci-and-release-integrity" tabindex="-1">Git, CI and release integrity <a class="header-anchor" href="#git-ci-and-release-integrity" aria-label="Permalink to “Git, CI and release integrity”">​</a></h1><p><strong>Prerequisites:</strong> Local status/diffs, project checks and the primary Node artifact/database material. Review baseline: 2026-10-27. All learner practice remains outstanding.</p><h2 id="select-a-release-policy" tabindex="-1"><span class="hub-section-number">1 </span>Select a release policy <a class="header-anchor" href="#select-a-release-policy" aria-label="Permalink to “1 Select a release policy”">​</a></h2><p><a href="./../senior_growth/Git/GIT_flow_vs_Trunk-based_Development%2C_Differences%2C_benefits_each_of_branching_model.html">Branching model comparison</a> → <a href="./../senior_growth/Git/Please_explain_the_git_strategy_in_your_project.html">Local strategy and conflict recovery</a> → <a href="./../senior_growth/Git/What&#39;s_the_difference_between_merge_and_rebase_in_git_What&#39;s_prefferable.html">Merge/rebase mechanics</a>. Team size is not the deciding variable. A branch label is not protection; a conflict-free merge can still be wrong. Never push from this assistant workflow.</p><h2 id="enforce-without-damaging-work" tabindex="-1"><span class="hub-section-number">2 </span>Enforce without damaging work <a class="header-anchor" href="#enforce-without-damaging-work" aria-label="Permalink to “2 Enforce without damaging work”">​</a></h2><p><a href="./../senior_growth/Git/What_is_GIT_hooks_Which_git_hooks_you_are_using_on_your_current_project_and_why.html">Staged-aware hooks</a> and <a href="./../senior_growth/CD_CI/Do_you_run_tests_within_CICD.html">Isolated CI jobs</a>. Local hooks may be bypassed; required remote checks are separate policy. Check exact candidate bytes; caches are optional accelerators, artifacts are explicit handoffs.</p><h2 id="separate-build-from-promotion" tabindex="-1"><span class="hub-section-number">3 </span>Separate build from promotion <a class="header-anchor" href="#separate-build-from-promotion" aria-label="Permalink to “3 Separate build from promotion”">​</a></h2><p><a href="./../senior_growth/CD_CI/What_is_Continuous_Integration%2C_Continous_Delivery%2C_Continous_Deployment.html">CI/delivery/deployment</a> → <a href="./../senior_growth/CD_CI/Release_strategies._What_strategy_do_you_use_on_project_How_will_you_build_a_release_strategy_for_open_source_project.html">Schema-compatible rollout</a> → <a href="./../node-js/release-artifact-compatibility.html">real artifact compatibility</a>. Rolling deployment, canary and version/support policy are distinct choices. A code rollback is unsafe after incompatible data/messages have been committed.</p><h2 id="keep-untrusted-ci-code-outside-release-authority" tabindex="-1"><span class="hub-section-number">4 </span>Keep untrusted CI code outside release authority <a class="header-anchor" href="#keep-untrusted-ci-code-outside-release-authority" aria-label="Permalink to “4 Keep untrusted CI code outside release authority”">​</a></h2><p>A dependency install or build can execute repository-controlled code. Use isolated unprivileged checks for untrusted changes; do not expose production secrets or a privileged runner merely to run a PR test. Lockfiles and hashes identify inputs/bytes but do not establish trust. Privileged promotion needs a reviewed candidate/artifact provenance and narrow authority. No hosted pipeline or deployment is activated by these notes.</p><h2 id="promotion-is-a-separate-authority" tabindex="-1"><span class="hub-section-number">5 </span>Promotion is a separate authority <a class="header-anchor" href="#promotion-is-a-separate-authority" aria-label="Permalink to “5 Promotion is a separate authority”">​</a></h2>',11)),s(t,{"encoded-source":"flowchart%20TD%0A%20%20Change%5BCandidate%20source%20identity%5D%20--%3E%20Checks%5BIsolated%20unprivileged%20checks%5D%0A%20%20Checks%20--%3E%20Artifact%5BImmutable%20artifact%20and%20digest%5D%0A%20%20Artifact%20--%3E%20Gate%5BReviewed%20release%20and%20schema%20gates%5D%0A%20%20Gate%20--%3E%20Promotion%5BAuthorized%20promotion%20decision%5D%0A%20%20Promotion%20--%3E%20Observe%5BHealth%20and%20compatibility%20observation%5D"}),e[1]||(e[1]=a('<p>This is a conceptual ownership map. It neither publishes a pipeline nor grants a check job production credentials.</p><h2 id="practice-and-verification" tabindex="-1"><span class="hub-section-number">6 </span>Practice and verification <a class="header-anchor" href="#practice-and-verification" aria-label="Permalink to “6 Practice and verification”">​</a></h2><p>Use <a href="./../practice/engineering/">the shared increments</a> and linked focused requirements. <a href="./../workbench/engineering/">Workbench</a> contains canonical references; <a href="./../review/verification.html">verification</a> distinguishes current checks, preserved historical evidence and unperformed integrations.</p>',3))])}const g=r(c,[["render",l]]);export{f as __pageData,g as default};
